import{_ as t,o as a,c as e,ae as n}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-06-09","description":"","frontmatter":{"date":"2026-06-09T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-06-09-uxtrend.md","filePath":"daily/2026-06-09-uxtrend.md"}'),o={name:"daily/2026-06-09-uxtrend.md"};function s(i,r,g,p,h,l){return a(),e("div",null,[...r[0]||(r[0]=[n('<h1 id="设计趋势-2026-06-09" tabindex="-1">设计趋势 - 2026-06-09 <a class="header-anchor" href="#设计趋势-2026-06-09" aria-label="Permalink to &quot;设计趋势 - 2026-06-09&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势聚焦于AI在工作流、创造方式、交互模式和用户体验中的应用。AI代理工作流设计模式强调其作为任务协调器的角色，而AI在设计中的应用预示着创作方式的变革，提升适应性和团队协作。最值得关注的趋势是AI交互模式的建立，它通过交互模式建立人与AI之间的信任关系，以及设计代理型用户体验指南，它从即时任务导向转变为预测用户未知需求的代理型设计。</p><hr><h3 id="_1-ai代理工作流设计模式概览" tabindex="-1">1. AI代理工作流设计模式概览 <a class="header-anchor" href="#_1-ai代理工作流设计模式概览" aria-label="Permalink to &quot;1. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview | by Craig Li, Ph.D</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，强调工作流作为任务协调器的作用。</p><p><strong>能解决什么问题</strong>: 如何使AI代理更有效地规划、执行任务并模拟人类推理。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过灵活的任务协调处理不同问题。</p><p><strong>示例场景</strong>: 开发基于这些原则的AI代理，处理复杂问题解决。</p><hr><h3 id="_2-ai在设计中的应用-改变我们的创造方式" tabindex="-1">2. AI在设计中的应用：改变我们的创造方式 <a class="header-anchor" href="#_2-ai在设计中的应用-改变我们的创造方式" aria-label="Permalink to &quot;2. AI在设计中的应用：改变我们的创造方式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/ai-in-design" target="_blank" rel="noreferrer">AI in Design: Transforming the Way We Create - Figma</a></p><p><strong>一句话摘要</strong>: AI将深度整合进设计工作流程，提升创作适应性和团队协作。</p><p><strong>能解决什么问题</strong>: 解决设计任务自动化和预测设计师需求的问题。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI提高设计效率和个性化体验。</p><p><strong>示例场景</strong>: 使用AI设计工具根据用户行为定制化界面布局。</p><hr><h3 id="_3-ai交互模式-让用户识别并互动ai驱动功能" tabindex="-1">3. AI交互模式：让用户识别并互动AI驱动功能 <a class="header-anchor" href="#_3-ai交互模式-让用户识别并互动ai驱动功能" aria-label="Permalink to &quot;3. AI交互模式：让用户识别并互动AI驱动功能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@flik185/ai-interaction-patterns-giving-users-ways-to-recognize-and-interact-with-ai-driven-features-22055a91206b" target="_blank" rel="noreferrer">AI Interaction Patterns: Giving Users Ways to Recognize and Interact With Ai-Driven Features</a></p><p><strong>一句话摘要</strong>: 通过交互模式建立人与AI之间的信任关系</p><p><strong>能解决什么问题</strong>: 如何让用户识别并有效互动AI驱动的功能</p><p><strong>产品应用</strong>: 适用于AI工具，如聊天机器人、分析仪表板等</p><p><strong>示例场景</strong>: 在线客服聊天机器人提供个性化服务</p><hr><h3 id="_4-设计代理型用户体验指南" tabindex="-1">4. 设计代理型用户体验指南 <a class="header-anchor" href="#_4-设计代理型用户体验指南" aria-label="Permalink to &quot;4. 设计代理型用户体验指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ai-ux-designers/era-of-agentive-ux-not-agentic-64dd765a0372" target="_blank" rel="noreferrer">Designing for Agentive UX — A Guide</a></p><p><strong>一句话摘要</strong>: 从即时任务导向转变为预测用户未知需求的代理型设计。</p><p><strong>能解决什么问题</strong>: 如何设计能够预测并满足用户未来需求的智能代理。</p><p><strong>产品应用</strong>: 适用于需要个性化服务和预测用户行为的产品，如智能助手。</p><p><strong>示例场景</strong>: 智能助手根据用户习惯自动推荐新闻和文章。</p><hr><h3 id="_5-构建信任与增强互动-7个关键ai-ux模式的实际应用" tabindex="-1">5. 构建信任与增强互动：7个关键AI UX模式的实际应用 <a class="header-anchor" href="#_5-构建信任与增强互动-7个关键ai-ux模式的实际应用" aria-label="Permalink to &quot;5. 构建信任与增强互动：7个关键AI UX模式的实际应用&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/bestfolios/building-trust-and-enhancing-interactions-7-essential-ai-ux-patterns-in-action-12e7604de435" target="_blank" rel="noreferrer">Building Trust and Enhancing Interactions: 7 Essential AI UX Patterns in Action</a></p><p><strong>一句话摘要</strong>: AI UX模式通过上下文提及和智能代码块等提升交互体验。</p><p><strong>能解决什么问题</strong>: 解决AI交互中缺乏上下文和代码操作复杂的问题。</p><p><strong>产品应用</strong>: 可应用于编程助手和企业工具，提高开发效率和用户体验。</p><p><strong>示例场景</strong>: ChatGPT通过智能代码块实现代码的直接操作。</p><hr><h3 id="_6-2026年顶级网页设计趋势" tabindex="-1">6. 2026年顶级网页设计趋势 <a class="header-anchor" href="#_6-2026年顶级网页设计趋势" aria-label="Permalink to &quot;6. 2026年顶级网页设计趋势&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/web-design-trends" target="_blank" rel="noreferrer">Top Web Design Trends for 2026</a></p><p><strong>一句话摘要</strong>: AI技术正在使网站设计更加智能化和个性化。</p><p><strong>能解决什么问题</strong>: 提高网站交互性、可访问性和个性化体验。</p><p><strong>产品应用</strong>: 可以通过Figma Make等工具实现智能布局、交互代理和AI驱动体验。</p><p><strong>示例场景</strong>: 使用AI聊天机器人处理多步骤任务，预测用户需求。</p><hr><h3 id="_7-ai驱动的产品工程与设计-提升客户体验" tabindex="-1">7. AI驱动的产品工程与设计：提升客户体验 <a class="header-anchor" href="#_7-ai驱动的产品工程与设计-提升客户体验" aria-label="Permalink to &quot;7. AI驱动的产品工程与设计：提升客户体验&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@sneha.mehra/ai-driven-product-engineering-and-design-elevating-cx-afdc1d215e55" target="_blank" rel="noreferrer">AI-driven product engineering and design: Elevating CX</a></p><p><strong>一句话摘要</strong>: AI驱动的产品工程与设计是实现产品领先的关键。</p><p><strong>能解决什么问题</strong>: 解决客户体验不佳和产品创新速度慢的问题。</p><p><strong>产品应用</strong>: 可应用于产品设计初期，利用AI模型快速探索设计变体。</p><p><strong>示例场景</strong>: 使用生成设计工具优化系统微服务负载平衡。</p><hr><h3 id="_8-如何使用chatgpt新图像生成器创建ui" tabindex="-1">8. 如何使用ChatGPT新图像生成器创建UI <a class="header-anchor" href="#_8-如何使用chatgpt新图像生成器创建ui" aria-label="Permalink to &quot;8. 如何使用ChatGPT新图像生成器创建UI&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/how-i-created-ui-with-chatgpts-new-image-generator-4o-d52389a5833e" target="_blank" rel="noreferrer">How I created UI with ChatGPT’s new image generator (4o)</a></p><p><strong>一句话摘要</strong>: ChatGPT的新图像生成器大幅提升了UI视觉原型的生成能力。</p><p><strong>能解决什么问题</strong>: 解决UI设计师快速生成视觉原型的需求，提高设计效率。</p><p><strong>产品应用</strong>: 可以应用到产品设计初期，快速生成多种UI设计选项。</p><p><strong>示例场景</strong>: 设计师根据描述生成三种不同风格的UI视觉原型。</p><hr><h3 id="_9-ai工作流优化-7个实用技巧" tabindex="-1">9. AI工作流优化：7个实用技巧 <a class="header-anchor" href="#_9-ai工作流优化-7个实用技巧" aria-label="Permalink to &quot;9. AI工作流优化：7个实用技巧&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@vicki-larson/ai-workflow-optimization-7-game-changing-tips-that-actually-work-414862126f5f" target="_blank" rel="noreferrer">AI Workflow Optimization: 7 Game-Changing Tips That Actually Work</a></p><p><strong>一句话摘要</strong>: AI技术在设计工作流中的应用和优化。</p><p><strong>能解决什么问题</strong>: 提高设计效率，减少重复性工作。</p><p><strong>产品应用</strong>: 适用于需要快速原型和设计迭代的产品开发。</p><p><strong>示例场景</strong>: 使用AI工具生成布局结构和颜色方案。</p><hr><h3 id="_10-ai-ux-人工智能代理的体验设计" tabindex="-1">10. AI/UX：人工智能代理的体验设计 <a class="header-anchor" href="#_10-ai-ux-人工智能代理的体验设计" aria-label="Permalink to &quot;10. AI/UX：人工智能代理的体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/i-ux/ai-ux-experience-design-of-ai-agents-12e1051fa065" target="_blank" rel="noreferrer">AI/UX: Experience Design of AI Agents</a></p><p><strong>一句话摘要</strong>: AI代理通过学习提升服务，成为服务生态系统的活跃参与者。</p><p><strong>能解决什么问题</strong>: 如何将AI代理融入用户体验设计，提升服务效率和决策能力。</p><p><strong>产品应用</strong>: 适用于需要自动化和智能决策的领域，如健康、金融和旅游。</p><p><strong>示例场景</strong>: AI代理代表用户和航空公司比较票价和偏好。</p><hr>',75)])])}const u=t(o,[["render",s]]);export{c as __pageData,u as default};
